const meta = {
  component: Dialog,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage

A modal dialog for focused tasks. `DialogPanel` is the popup shell; `DialogContent` is its padded, scrollable body. Place `DialogHeader`, one required `DialogContent`, and optional `DialogFooter` directly inside `DialogPanel`, in that order. The panel owns the popup and keeps the header and footer visible while the content scrolls. Header and footer separators are built in.

**Import:** `@/registry/erbium/ui/dialog`

## Usage

```tsx
import {
  Dialog,
  DialogClose,
  DialogPanel,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogContent,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";
import { Button } from "@/registry/erbium/ui/button";
```

```tsx
<Dialog>
  <DialogTrigger render={<Button variant="outline">Open</Button>} />
  <DialogPanel>
    <DialogHeader>
      <DialogTitle>Edit profile</DialogTitle>
      <DialogDescription>Update your details.</DialogDescription>
    </DialogHeader>
    <DialogContent>Content</DialogContent>
    <DialogFooter>Actions</DialogFooter>
  </DialogPanel>
</Dialog>
```

## Composition

```text
Dialog
├── DialogTrigger
└── DialogPanel
    ├── DialogHeader
    │   ├── DialogTitle
    │   └── DialogDescription
    ├── DialogContent
    └── DialogFooter
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Dialog](https://base-ui.com/react/components/dialog)",
      },
    },
  },
} satisfies Meta<typeof Dialog>;

export default { ...meta, title: "Overlays & menus/Dialog",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

