import { Button } from "@/registry/erbium/ui/button";
import {
  Dialog,
  DialogClose,
  DialogPanel,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogContent,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";

export default function DialogCloseButton() {
  return (
    <Dialog>
      <DialogTrigger render={<Button variant="outline">Share</Button>} />
      <DialogPanel className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Share link</DialogTitle>
          <DialogDescription>Anyone who has this link will be able to view this.</DialogDescription>
        </DialogHeader>
        <DialogContent className="flex items-center gap-2">
          <Field className="flex-1">
            <FieldLabel className="sr-only">Link</FieldLabel>
            <Input defaultValue="https://ui.erbium.app/docs/installation" readOnly />
          </Field>
        </DialogContent>
        <DialogFooter className="sm:justify-start">
          <DialogClose
            render={
              <Button type="button" variant="secondary">
                Close
              </Button>
            }
          />
        </DialogFooter>
      </DialogPanel>
    </Dialog>
  );
}

import { useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import {
  Dialog,
  DialogClose,
  DialogPanel,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogContent,
  DialogTitle,
  DialogTrigger,
} from "@/registry/erbium/ui/dialog";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";

export default function DialogDemo() {
  const [open, setOpen] = useState(false);
  const [savedName, setSavedName] = useState<string | null>(null);
  return (
    <div className="flex flex-col items-center gap-3">
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogTrigger render={<Button variant="outline">Open Dialog</Button>} />
        <DialogPanel
          className="sm:max-w-[425px]"
          render={
            <form
              onSubmit={(event) => {
                event.preventDefault();
                const values = new FormData(event.currentTarget);
                const name = values.get("name");
                setSavedName(typeof name === "string" ? name : "");
                setOpen(false);
              }}
            />
          }
        >
          <DialogHeader>
            <DialogTitle>Edit profile</DialogTitle>
            <DialogDescription>
              Make changes to your profile here. Click save when you&apos;re done.
            </DialogDescription>
          </DialogHeader>
          <DialogContent className="grid content-start gap-4">
            <Field>
              <FieldLabel>Name</FieldLabel>
              <Input name="name" defaultValue="Pedro Duarte" />
            </Field>
            <Field>
              <FieldLabel>Username</FieldLabel>
              <Input name="username" defaultValue="@peduarte" />
            </Field>
          </DialogContent>
          <DialogFooter>
            <DialogClose render={<Button variant="outline">Cancel</Button>} />
            <StatefulButton type="submit">Save changes</StatefulButton>
          </DialogFooter>
        </DialogPanel>
      </Dialog>
      {savedName !== null && (
        <p role="status" className="text-sm text-muted-foreground">
          Saved profile for {savedName}.
        </p>
      )}
    </div>
  );
}

