import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout"
    >
      {children}
    </div>
  );
}
